import pyomo.environ as pyo

DATA = {
    "foods": ["Food_1", "Food_2", "Food_3", "Food_4", "Food_5", "Food_6"],
    "nutrients": ["protein", "carbs", "calories"],
    "cost": {
        "Food_1": 4,
        "Food_2": 2,
        "Food_3": 6,
        "Food_4": 2,
        "Food_5": 6,
        "Food_6": 8,
    },
    "content": {
        # content[food][nutrient]
        "Food_1": {"protein": 17, "carbs": 8,  "calories": 237},
        "Food_2": {"protein": 4,  "carbs": 24, "calories": 213},
        "Food_3": {"protein": 7,  "carbs": 27, "calories": 133},
        "Food_4": {"protein": 14, "carbs": 16, "calories": 118},
        "Food_5": {"protein": 13, "carbs": 1,  "calories": 136},
        "Food_6": {"protein": 1,  "carbs": 13, "calories": 225},
    },
    "requirement": {
        "protein": 76,
        "carbs": 173,
        "calories": 1751,
    },
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.F = pyo.Set(initialize=d["foods"])
    model.N = pyo.Set(initialize=d["nutrients"])

    model.servings = pyo.Var(
        model.F, within=pyo.NonNegativeReals, bounds=(0, None)
    )

    def obj_rule(m):
        return sum(d["cost"][f] * m.servings[f] for f in m.F)

    model.obj = pyo.Objective(expr=obj_rule, sense=pyo.minimize)

    def nutrient_rule(m, n):
        return sum(
            d["content"][f][n] * m.servings[f] for f in m.F
        ) >= d["requirement"][n]

    model.nutrient_req = pyo.Constraint(model.N, rule=nutrient_rule)

    return model


